 'invoices'=>['label'=>'Fatura ve proforma','group'=>'operations','fields'=>['title'=>$f('Belge adı','text',['required'=>true]),'orderId'=>$f('Sipariş','reference',['resource'=>'orders','required'=>true]),'connectionId'=>$f('KolayBi bağlantısı','connection'),'contactId'=>$f('KolayBi cari ID','integer',['min'=>1]),'addressId'=>$f('KolayBi adres ID','integer',['min'=>1]),'note'=>$f('Belge notu','textarea')]],
 'productMappings'=>['label'=>'KolayBi ürün eşleştirme','group'=>'operations','fields'=>['connectionId'=>$f('KolayBi bağlantısı','connection',['required'=>true]),'productId'=>$f('NODENO ürünü','product',['required'=>true]),'externalId'=>$f('KolayBi ürün ID','integer',['min'=>1,'required'=>true]),'vatRate'=>$f('Doğrulanmış KDV oranı','enum',['options'=>['0','1','10','20'],'required'=>true])]],
