function nodenoControlCommand(array $ctx,string $key,array $request,callable $action):array {
 if(!preg_match('/^[A-Za-z0-9_-]{16,100}$/D',$key))throw new NodenoControlHttpError(422,'idempotency_key_required');$db=$ctx['db'];$actor=$ctx['user']['id'];$keyHash=hash('sha256',$actor.'|'.$key);$hash=hash('sha256',json_encode($request,JSON_THROW_ON_ERROR));return nodenoControlTransaction($db,static function()use($db,$actor,$keyHash,$hash,$action):array{$q=$db->prepare('SELECT * FROM control_commands WHERE key_hash=?');$q->execute([$keyHash]);$old=$q->fetch();if($old){if(!hash_equals($old['request_hash'],$hash))throw new NodenoControlHttpError(409,'idempotency_conflict');return json_decode($old['response_json'],true);}$result=$action();$db->prepare('INSERT INTO control_commands(key_hash,actor_id,request_hash,response_json,created_at) VALUES(?,?,?,?,?)')->execute([$keyHash,$actor,$hash,json_encode($result,JSON_THROW_ON_ERROR),time()]);return $result;});
}
function nodenoControlItems(array $items,array $catalog):array {
 if(!$items||count($items)>100)throw new NodenoControlHttpError(422,'items_invalid');$byId=array_column($catalog['products'],null,'id');$out=[];$seen=[];$total=0;foreach($items as $item){$p=$byId[$item['productId']??'']??null;$quantity=$item['quantity']??null;if(!$p||!is_int($quantity)||$quantity<1||$quantity>99||isset($seen[$p['id']]))throw new NodenoControlHttpError(422,'item_invalid');$price=$p['salePriceMinor']??null;if(($p['currency']??'')!=='TRY'||!is_int($price)||$price<=0||$price>10000000000)throw new NodenoControlHttpError(422,'product_price_unavailable');$seen[$p['id']]=true;$out[]=['productId'=>$p['id'],'quantity'=>$quantity,'unitPriceMinor'=>$price,'code'=>$p['code'],'title'=>$p['name']['tr']??$p['code']];$total+=$price*$quantity;}return ['items'=>$out,'totalMinor'=>$total];
}
function nodenoControlOperationValidate(array $ctx,string $resource,?array $old,array $data):void {
 if($resource==='productMappings'||($resource==='invoices'&&(isset($data['contactId'])||isset($data['addressId'])))){$connection=nodenoControlSetting($ctx['db'],'integration:kolaybi');if(!$connection||($connection['status']??'')!=='connected'||!is_string($data['connectionId']??null)||!hash_equals((string)($connection['connectionId']??''),$data['connectionId']))throw new NodenoControlHttpError(422,'kolaybi_connection_mismatch');if($resource==='invoices'&&(!isset($data['contactId'])||!isset($data['addressId'])))throw new NodenoControlHttpError(422,'kolaybi_contact_mapping_required');}
 if($resource==='orders'&&!in_array($data['status']??'',['draft','prepared','cancelled'],true))throw new NodenoControlHttpError(422,'payment_not_enabled');
 if($resource==='orders'&&$old&&$old['data']['status']==='cancelled'&&($data['status']??'')!=='cancelled')throw new NodenoControlHttpError(409,'order_cancelled');
 if($resource==='shipments'){$order=nodenoControlRead($ctx['db'],'orders',$data['orderId']);if(!$order)throw new NodenoControlHttpError(422,'order_unknown');$carrier=nodenoControlRead($ctx['db'],'carriers',$data['carrierId']);if(!$carrier||empty($carrier['data']['enabled']))throw new NodenoControlHttpError(422,'carrier_unavailable');if($order['data']['status']==='cancelled')throw new NodenoControlHttpError(422,'order_cancelled');if(($data['status']??'')!=='preparing')throw new NodenoControlHttpError(422,'confirmed_order_required');}
 if($resource==='invoices'&&!nodenoControlRead($ctx['db'],'orders',$data['orderId']))throw new NodenoControlHttpError(422,'order_unknown');
 if($resource==='messages'){if(!in_array($data['status']??'',['draft','cancelled'],true))throw new NodenoControlHttpError(422,'provider_not_connected');if(($data['purpose']??'')==='marketing'&&(empty($data['consent'])||empty($data['consentReference'])))throw new NodenoControlHttpError(422,'marketing_consent_required');}
 if($resource==='shipping'&&isset($data['minimumDays'],$data['maximumDays'])&&$data['maximumDays']<$data['minimumDays'])throw new NodenoControlHttpError(422,'shipping_days_invalid');
}
function nodenoControlShippingQuote(PDO $db,int $total,string $country):array {
 $rules=[];foreach(nodenoControlPublished($db,'shipping') as $r)if(($r['data']['country']??'')===$country&&!empty($r['data']['enabled']))$rules[]=$r['data'];if(!$rules)return ['available'=>false,'feeMinor'=>null];usort($rules,static fn($a,$b)=>$a['feeMinor']<=>$b['feeMinor']);$r=$rules[0];$fee=isset($r['freeAboveMinor'])&&$r['freeAboveMinor']>0&&$total>=$r['freeAboveMinor']?0:$r['feeMinor'];return ['available'=>true,'currency'=>'TRY','feeMinor'=>$fee,'minimumDays'=>$r['minimumDays']??null,'maximumDays'=>$r['maximumDays']??null];
}
function nodenoControlDocument(array $ctx,string $orderId,string $kind):string {
 nodenoControlRequire($ctx,'operations.read');$order=nodenoControlRead($ctx['db'],'orders',$orderId);if(!$order)throw new NodenoControlHttpError(404,'not_found');$d=$order['data'];$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$title=$kind==='packing'?'Paketleme listesi':'Proforma';$rows='';foreach($d['items'] as $item)$rows.='<tr><td>'.$e($item['code']).'</td><td>'.$e($item['title']).'</td><td>'.$e($item['quantity']).'</td>'.($kind==='packing'?'':'<td>'.$e(number_format($item['unitPriceMinor']/100,2,',','.')).' TRY</td>').'</tr>';return '<!doctype html><html lang="tr"><meta charset="utf-8"><meta name="robots" content="noindex,nofollow"><title>NODENO '.$title.'</title><link rel="stylesheet" href="/admin.css"><body class="document"><img src="/assets/brand/logo-horizontal.svg" width="180" alt="NODENO"><h1>'.$title.'</h1><p>Mali belge değildir. Sipariş veya ödeme onayı yerine geçmez.</p><p>'.$e($orderId).'</p><h2>'.$e($d['title']).'</h2><p>'.$e($d['address']).'</p><table><thead><tr><th>Kod</th><th>Ürün</th><th>Adet</th>'.($kind==='packing'?'':'<th>Birim fiyat</th>').'</tr></thead><tbody>'.$rows.'</tbody></table>'.($kind==='packing'?'':'<p>Ürün toplamı: '.$e(number_format($d['totalMinor']/100,2,',','.')).' TRY. Kargo ve ülkeye bağlı ek bedeller dahil değildir.</p>').'</body></html>';
}
